<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class CategoryRequest extends FormRequest { public function authorize():bool{return $this->user()->can('category.manage');} public function rules():array{return ['nama_kategori'=>'required|string|max:100|unique:categories,nama_kategori,'.($this->category?->id??'NULL'),'deskripsi'=>'nullable|string'];} }
